#include <stdlib.h>
#include <string.h>
#include "short.h"

typedef struct node {
  char *key;
  char *val;
  struct node *next;
} node;

struct short_table {
  node **buckets;
  size_t nbuckets;
  size_t len;
};

static char *copy(const char *s) {
  size_t n = strlen(s) + 1;
  char *c = malloc(n);
  if (c) memcpy(c, s, n);
  return c;
}

short_table *table_new(size_t buckets) {
  if (buckets == 0) buckets = 1;
  short_table *t = malloc(sizeof *t);
  if (!t) return NULL;
  t->buckets = calloc(buckets, sizeof *t->buckets);
  if (!t->buckets) {
    free(t);
    return NULL;
  }
  t->nbuckets = buckets;
  t->len = 0;
  return t;
}

void table_free(short_table *t) {
  if (!t) return;
  for (size_t i = 0; i < t->nbuckets; i++) {
    node *n = t->buckets[i];
    while (n) {
      node *next = n->next;
      free(n->key);
      free(n->val);
      free(n);
      n = next;
    }
  }
  free(t->buckets);
  free(t);
}

static node *find(const short_table *t, const char *key, size_t *bucket) {
  size_t b = short_hash(key) % t->nbuckets;
  if (bucket) *bucket = b;
  for (node *n = t->buckets[b]; n; n = n->next)
    if (strcmp(n->key, key) == 0) return n;
  return NULL;
}

int table_set(short_table *t, const char *key, const char *val) {
  if (!t || !key || !val) return -1;
  size_t b;
  node *n = find(t, key, &b);
  char *v = copy(val);
  if (!v) return -1;
  if (n) {
    free(n->val);
    n->val = v;
    return 0;
  }
  n = malloc(sizeof *n);
  char *k = copy(key);
  if (!n || !k) {
    free(n);
    free(k);
    free(v);
    return -1;
  }
  n->key = k;
  n->val = v;
  n->next = t->buckets[b];
  t->buckets[b] = n;
  t->len++;
  return 0;
}

const char *table_get(const short_table *t, const char *key) {
  if (!t || !key) return NULL;
  node *n = find(t, key, NULL);
  return n ? n->val : NULL;
}

size_t table_len(const short_table *t) { return t ? t->len : 0; }
